"""Reconcile old finite ground jobs against the current native source owners."""
from . import geometry as g
from .design import HERE as SOURCE

def run():
 plan=g.CITY/'registered_integration/r8/coverage_plan';base=g.np.load(plan/'baseline_masks.npz');old=g.load(plan/'ground_program_units.json');labels=g.np.load(plan/'ground_unit_labels.npz')['unit_labels'];bulkpath=SOURCE/'coherent_regrade_r01/bulk_placements_r02.json';bulk=g.load(bulkpath);g.GRID=1.;g.BOUNDS=base['bounds'].tolist();g.NZ,g.NX=labels.shape;g.SHAPE=labels.shape;g.XS=g.BOUNDS[0]+g.np.arange(g.NX)+.5;g.ZS=g.BOUNDS[1]+g.np.arange(g.NZ)+.5;layouts=[g.load(g.ROOT/g.load((g.ROOT/d['pack']['path']))['layout']['path'])for d in bulk['districts']];holdings=[h for l in layouts for h in l['holdings']];holdmask=g.raster([h['holding_polygon_xz_m']for h in holdings]);roofs=g.raster([q for l in layouts for p in l['placements']for q in p['native_roof_polygons_xz_m']]);routes=g.raster([q for h in holdings for q in h['external_route_polygons_xz_m']]+[q for l in layouts for r in l['shared_private_routes']for q in r['polygons_xz_m']]);retired=set(bulk['replaced_placement_ids']);projection=g.load(plan/'native_projection.json')['instances'];retained=g.raster([q for i in projection if i['id']not in retired for q in i['roof_parts_xz_m']]);special=g.raster(g.load(SOURCE/'owner_route_source_snapshot.json')['special_reserved_polygon_parts_xz_m']);protected=g.np.logical_or.reduce([base[k]for k in['spaces','estates','water','road','wall','retained_native','retained_access']])|special;mill=g.load(SOURCE/'coherent_regrade_r01/mill_reservation_check.json');protected|=g.raster([r['polygon']for r in mill['protected_regions']]);covered=holdmask|routes|retained|protected;units=[];mapping={h.get('source_holding_id'):h['id']for h in holdings if h.get('source_holding_id')};count=0
 for i,u in enumerate(old['units'],1):
  m=labels==i
  if not m.any():continue
  residual=m&~covered;amount=int(residual.sum());count+=amount
  units.append(dict(id=u['id'],block_id=u['block_id'],original_source_function=u['source_function'],original_owner=u.get('provisional_owner_holding_or_native_id'),replacement_owner=mapping.get(u.get('provisional_owner_holding_or_native_id')),original_grid_area_m2=int(m.sum()),now_inside_new_holding_m2=int((m&holdmask).sum()),now_inside_reserved_route_m2=int((m&routes&~holdmask).sum()),now_retained_or_protected_m2=int((m&(retained|protected)&~(holdmask|routes)).sum()),remaining_program_area_m2=amount,remaining_polygon_parts_xz_m=g.parts(residual)if amount>=25 else[],status='SUPERSEDED_BY_NATIVE_SOURCE_OWNER'if amount==0 else'REMAINING_PHYSICAL_GROUND_PROGRAM',actual_scene_complete=False))
 blocks=[];bdefs=g.load(plan/'baseline_blocks.json')['blocks']
 for i,b in enumerate(bdefs,1):
  domain=(base['block_labels']==i)&~protected;residual=domain&~(holdmask|routes|retained);components,n=g.ndimage.label(residual);regions=[]
  for j in range(1,n+1):
   rr=components==j;ar=int(rr.sum())
   if ar>=25:regions.append(dict(id=b['block_id']+f':RESIDUAL:{j:04}',area_m2=ar,polygon_parts_xz_m=g.parts(rr),required_use='Bounded productive, domestic or manual-working ground with an actual connected entrance, or a reviewed physical exclusion.',status='UNFINISHED_PHYSICAL_GROUND'))
  blocks.append(dict(block_id=b['block_id'],ordinary_effective_domain_grid_m2=int(domain.sum()),new_holding_grid_m2=int((domain&holdmask).sum()),native_roof_grid_m2=int((domain&(roofs|retained)).sum()),remaining_unowned_ground_grid_m2=int(residual.sum()),meaningful_remaining_regions=regions,meaningful_threshold_m2=25,whole_block_complete=False))
 report=dict(schema='riverstone.district_fabric.ground_reconciliation.v1',native_bulk=g.ref(bulkpath),old_ground_program=g.ref(plan/'ground_program_units.json'),planning_grid_m=1,area_measure='One-metre center-sampled accounting. Exact native/source vectors remain in the linked packs; these accounting rectangles are not terrain-edit geometry.',units=units,blocks=blocks,summary=dict(original_ground_units=len(old['units']),reconciled_units=len(units),fully_superseded_units=sum(u['remaining_program_area_m2']==0 for u in units),remaining_program_grid_m2=count,remaining_unowned_ground_grid_m2=sum(b['remaining_unowned_ground_grid_m2']for b in blocks),remaining_meaningful_regions=sum(len(b['meaningful_remaining_regions'])for b in blocks)),completion_claim='Native building/court source is substantially expanded. Remaining physical grounds stay explicit; neither this accounting nor unimplemented source labels certify whole-city completion.')
 g.write(SOURCE/'coherent_regrade_r01/ground_reconciliation.json',report);print(report['summary'])
if __name__=='__main__':run()
